public sealed record CreateSubtaskRequest(string? Title,Guid? CreatedByUserId,long? TaskVersion); public sealed record UpdateSubtaskRequest(string? Title,long? TaskVersion); public sealed record SubtaskActionRequest(Guid? UserId,long? TaskVersion); public sealed record SubtaskVersionRequest(long? TaskVersion); public sealed record SubtaskOrderItem(Guid SubtaskId,int Position); public sealed record ReorderSubtasksRequest(long? TaskVersion,IReadOnlyList<SubtaskOrderItem>? Subtasks); public sealed record SubtaskUserResponse(Guid Id,string FullName); public sealed record SubtaskResponse(Guid Id,Guid TaskId,string Title,int Position,bool IsCompleted,SubtaskUserResponse CreatedBy,DateTimeOffset CreatedAt,SubtaskUserResponse? CompletedBy,DateTimeOffset? CompletedAt,DateTimeOffset UpdatedAt,long? TaskVersion);
internal static class SubtasksEndpoints{public static void MapEndpoints(IEndpointRouteBuilder a){var g=a.MapGroup("/api/tasks").WithTags("Subtasks");g.MapPost("/{taskId:guid}/subtasks",Create);g.MapGet("/{taskId:guid}/subtasks",List);g.MapPut("/{taskId:guid}/subtasks/{id:guid}",Update);g.MapDelete("/{taskId:guid}/subtasks/{id:guid}",Delete);g.MapPost("/{taskId:guid}/subtasks/{id:guid}/complete",Complete);g.MapPost("/{taskId:guid}/subtasks/{id:guid}/reopen",Reopen);g.MapPut("/{taskId:guid}/subtasks/order",Order);}static IResult P(string x,int s)=>Results.Problem(type:$"https://nakama/errors/{x}",statusCode:s);static bool Mutable(WorkTask t)=>t.Status is DomainTaskStatus.Pending or DomainTaskStatus.InProgress or DomainTaskStatus.Blocked;static async Task<(WorkTask? t,IResult? e)> Task(Guid id,long? v,NakamaDbContext d,CancellationToken c){var t=await d.Tasks.SingleOrDefaultAsync(x=>x.Id==id,c);if(t is null)return(null,P("task-not-found",404));if(!Mutable(t))return(null,P("task-subtasks-read-only",409));if(v is not>0||v!=t.Version)return(null,P("task-version-conflict",409));return(t,null);}static async Task<IResult>Create(Guid taskId,CreateSubtaskRequest r,NakamaDbContext d,IClock c,CancellationToken x){var q=await Task(taskId,r.TaskVersion,d,x);if(q.e is not null)return q.e;if(r.CreatedByUserId is not{} u)return P("task-validation",400);var user=await d.Users.SingleOrDefaultAsync(z=>z.Id==u,x);if(user is null)return P("user-not-found",404);if(!user.IsActive)return P("subtask-user-inactive",409);if(!await d.ProjectMembers.AnyAsync(z=>z.ProjectId==q.t!.ProjectId&&z.UserId==u,x))return P("subtask-user-not-project-member",409);await using var tx=await d.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,x);try{var pos=(await d.Subtasks.Where(z=>z.TaskId==taskId).MaxAsync(z=>(int?)z.Position,x)??0)+1;var s=Subtask.Create(taskId,r.Title??"",pos,u,c);d.Subtasks.Add(s);q.t.ChangeAssignments(c);d.Entry(q.t).Property(z=>z.Version).OriginalValue=r.TaskVersion!.Value;await d.SaveChangesAsync(x);await tx.CommitAsync(x);return Results.Created($"/api/tasks/{taskId}/subtasks/{s.Id}",new SubtaskResponse(s.Id,taskId,s.Title,s.Position,false,new(u,user.FullName),s.CreatedAt,null,null,s.UpdatedAt,q.t.Version));}catch(ArgumentException){return P("task-validation",400);}catch(DbUpdateConcurrencyException){return P("task-version-conflict",409);}}
static async Task<IResult>List(Guid taskId,NakamaDbContext d,CancellationToken x){if(!await d.Tasks.AnyAsync(z=>z.Id==taskId,x))return P("task-not-found",404);var list=await d.Subtasks.AsNoTracking().Where(z=>z.TaskId==taskId).OrderBy(z=>z.Position).ToListAsync(x);var ids=list.Select(z=>z.CreatedByUserId).Concat(list.Where(z=>z.CompletedByUserId!=null).Select(z=>z.CompletedByUserId!.Value)).Distinct();var us=await d.Users.Where(z=>ids.Contains(z.Id)).ToDictionaryAsync(z=>z.Id,x);return Results.Ok(list.Select(s=>new SubtaskResponse(s.Id,s.TaskId,s.Title,s.Position,s.IsCompleted,new(s.CreatedByUserId,us[s.CreatedByUserId].FullName),s.CreatedAt,s.CompletedByUserId is{} id?new(id,us[id].FullName):null,s.CompletedAt,s.UpdatedAt,null)));}
static async Task<IResult> Update(Guid taskId,Guid id,UpdateSubtaskRequest r,NakamaDbContext d,IClock c,CancellationToken x){var q=await Task(taskId,r.TaskVersion,d,x);if(q.e is not null)return q.e;var s=await d.Subtasks.SingleOrDefaultAsync(z=>z.Id==id&&z.TaskId==taskId,x);if(s is null)return P("subtask-not-found",404);try{s.UpdateTitle(r.Title??"",c);q.t!.ChangeAssignments(c);d.Entry(q.t).Property(z=>z.Version).OriginalValue=r.TaskVersion!.Value;await d.SaveChangesAsync(x);return Results.NoContent();}catch(ArgumentException){return P("task-validation",400);}catch(DbUpdateConcurrencyException){return P("task-version-conflict",409);}}
static async Task<IResult> Complete(Guid taskId,Guid id,SubtaskActionRequest r,NakamaDbContext d,IClock c,CancellationToken x)=>await Act(taskId,id,r,d,c,x,true);static async Task<IResult> Reopen(Guid taskId,Guid id,SubtaskActionRequest r,NakamaDbContext d,IClock c,CancellationToken x)=>await Act(taskId,id,r,d,c,x,false);static async Task<IResult>Act(Guid taskId,Guid id,SubtaskActionRequest r,NakamaDbContext d,IClock c,CancellationToken x,bool complete){var q=await Task(taskId,r.TaskVersion,d,x);if(q.e is not null)return q.e;if(r.UserId is not{} u||!await d.Users.AnyAsync(z=>z.Id==u&&z.IsActive,x))return P("subtask-user-inactive",409);if(!await d.ProjectMembers.AnyAsync(z=>z.ProjectId==q.t!.ProjectId&&z.UserId==u,x))return P("subtask-user-not-project-member",409);var s=await d.Subtasks.SingleOrDefaultAsync(z=>z.Id==id&&z.TaskId==taskId,x);if(s is null)return P("subtask-not-found",404);try{if(complete)s.Complete(u,c);else s.Reopen(c);q.t.ChangeAssignments(c);d.Entry(q.t).Property(z=>z.Version).OriginalValue=r.TaskVersion!.Value;await d.SaveChangesAsync(x);return Results.NoContent();}catch(InvalidOperationException){return P(complete?"subtask-already-completed":"subtask-not-completed",409);}catch(DbUpdateConcurrencyException){return P("task-version-conflict",409);}}
static async Task<IResult>Delete(Guid taskId,Guid id,[FromBody]SubtaskVersionRequest r,NakamaDbContext d,IClock c,CancellationToken x){var q=await Task(taskId,r.TaskVersion,d,x);if(q.e is not null)return q.e;var s=await d.Subtasks.SingleOrDefaultAsync(z=>z.Id==id&&z.TaskId==taskId,x);if(s is null)return P("subtask-not-found",404);await using var tx=await d.Database.BeginTransactionAsync(x);d.Subtasks.Remove(s);await d.SaveChangesAsync(x);var rest=await d.Subtasks.Where(z=>z.TaskId==taskId).OrderBy(z=>z.Position).ToListAsync(x);for(var i=0;i<rest.Count;i++)rest[i].Reposition(i+1);q.t!.ChangeAssignments(c);d.Entry(q.t).Property(z=>z.Version).OriginalValue=r.TaskVersion!.Value;await d.SaveChangesAsync(x);await tx.CommitAsync(x);return Results.NoContent();}
static async Task<IResult>Order(Guid taskId,ReorderSubtasksRequest r,NakamaDbContext d,IClock c,CancellationToken x){var q=await Task(taskId,r.TaskVersion,d,x);if(q.e is not null)return q.e;var all=await d.Subtasks.Where(z=>z.TaskId==taskId).ToListAsync(x);var a=r.Subtasks;if(a is null||a.Count!=all.Count||a.Select(z=>z.SubtaskId).Distinct().Count()!=a.Count||!a.Select(z=>z.Position).OrderBy(z=>z).SequenceEqual(Enumerable.Range(1,a.Count))||a.Any(z=>all.All(s=>s.Id!=z.SubtaskId)))return P("subtask-order-invalid",400);await using var tx=await d.Database.BeginTransactionAsync(x);await d.Subtasks.Where(z=>z.TaskId==taskId).ExecuteUpdateAsync(z=>z.SetProperty(s=>s.Position,s=>s.Position+all.Count),x);foreach(var i in a)await d.Subtasks.Where(z=>z.Id==i.SubtaskId).ExecuteUpdateAsync(z=>z.SetProperty(s=>s.Position,i.Position).SetProperty(s=>s.UpdatedAt,c.UtcNow),x);q.t!.ChangeAssignments(c);d.Entry(q.t).Property(z=>z.Version).OriginalValue=r.TaskVersion!.Value;try{await d.SaveChangesAsync(x);await tx.CommitAsync(x);return Results.NoContent();}catch(DbUpdateConcurrencyException){return P("task-version-conflict",409);}}}
